const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Somalia geometry
  const somalia = ee.Geometry.Rectangle([40.31659, -1.68325, 51.41903, 11.9182]);

  // 2. Define time periods
  const april2019Start = '2019-04-01';
  const april2019End = '2019-04-30';
  const baselineYears = [2015, 2016, 2017, 2018, 2020, 2021]; // Average Aprils excluding 2019

  // 3. Load GLDAS soil moisture data
  const gldas = ee.ImageCollection('NASA/GLDAS/V021/NOAH/G025/T3H');

  // 4. Filter for April 2019
  const april2019Col = gldas
    .filterDate(april2019Start, april2019End)
    .filterBounds(somalia)
    .select('SoilMoi0_10cm_inst');

  const april2019Size = april2019Col.size().getInfo();
  print('April 2019 Images: ' + april2019Size);

  if (april2019Size === 0) {
    print('No GLDAS data for April 2019');
    print('C1');
    return;
  }

  // 5. Calculate April 2019 mean soil moisture
  const april2019Mean = april2019Col
    .mean()
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: somalia,
      scale: 27830,
      maxPixels: 1e9
    })
    .get('SoilMoi0_10cm_inst')
    .getInfo();

  print('April 2019 Mean SM: ' + april2019Mean);

  if (april2019Mean === null || april2019Mean === undefined) {
    print('C2');
    return;
  }

  // 6. Build baseline: collect all other Aprils
  let baselineCol = ee.ImageCollection([]);

  for (let year of baselineYears) {
    const aprilStart = year + '-04-01';
    const aprilEnd = year + '-04-30';
    const yearCol = gldas
      .filterDate(aprilStart, aprilEnd)
      .filterBounds(somalia)
      .select('SoilMoi0_10cm_inst');
    baselineCol = baselineCol.merge(yearCol);
  }

  const baselineSize = baselineCol.size().getInfo();
  print('Baseline April Images: ' + baselineSize);

  if (baselineSize === 0) {
    print('No baseline April data available');
    print('C1');
    return;
  }

  // 7. Calculate baseline mean
  const baselineMean = baselineCol
    .mean()
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: somalia,
      scale: 27830,
      maxPixels: 1e9
    })
    .get('SoilMoi0_10cm_inst')
    .getInfo();

  print('Baseline Avg SM: ' + baselineMean);

  if (baselineMean === null || baselineMean === undefined) {
    print('C3');
    return;
  }

  // 8. Compare and determine answer
  print('Difference (2019 - Baseline): ' + (april2019Mean - baselineMean).toFixed(4));

  if (april2019Mean < baselineMean) {
    print('A');
  } else {
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
